"use client";

import { type FormEvent, type ReactNode, useId, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import {
  NativeSelect,
  NativeSelectOption,
} from "@/components/ui/native-select";
import { Textarea } from "@/components/ui/textarea";
import {
  type DashboardFilter,
  type DashboardFilterType,
  type DashboardKpiMetric,
  type DashboardOverflow,
  type DashboardTableInfo,
  type DashboardTranslate,
  type DashboardView,
  type DashboardWidget,
  type DashboardWidgetDraft,
  type DashboardWidgetType,
  dashboardCompareDayOptions,
  dashboardDateColumns,
  dashboardMetricOptions,
  dashboardWidgetFromDraft,
  emptyWidgetDraft,
  filterableColumns,
} from "./dashboard-model";
import type { DashboardLabel } from "./dashboard-widget";

function Field({
  children,
  htmlFor,
  label,
}: {
  children: ReactNode;
  htmlFor: string;
  label: string;
}) {
  return (
    <div className="grid gap-1.5">
      <label className="font-medium text-sm" htmlFor={htmlFor}>
        {label}
      </label>
      {children}
    </div>
  );
}

/** A checkbox with its label on the right. */
function CheckField({
  checked,
  disabled,
  id,
  label,
  onChange,
}: {
  checked: boolean;
  disabled?: boolean;
  id: string;
  label: string;
  onChange: (checked: boolean) => void;
}) {
  return (
    <div className="flex items-center gap-2">
      <input
        checked={checked}
        className="size-4 accent-primary"
        disabled={disabled}
        id={id}
        onChange={(event) => onChange(event.target.checked)}
        type="checkbox"
      />
      <label className="text-sm" htmlFor={id}>
        {label}
      </label>
    </div>
  );
}

const NUMBER_TYPES = new Set(["number", "currency", "percent"]);

export interface AddWidgetDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  tables: Record<string, DashboardTableInfo>;
  views: Record<string, DashboardView[] | undefined>;
  label: DashboardLabel;
  locale: string;
  translate: DashboardTranslate;
  onAdd: (widget: Omit<DashboardWidget, "id">) => void;
}

function TableFields({
  draft,
  ids,
  label,
  setDraft,
  tables,
  views,
}: {
  draft: DashboardWidgetDraft;
  ids: Record<string, string>;
  label: DashboardLabel;
  setDraft: (draft: DashboardWidgetDraft) => void;
  tables: Record<string, DashboardTableInfo>;
  views: Record<string, DashboardView[] | undefined>;
}) {
  return (
    <>
      <Field htmlFor={ids.table} label={label("table")}>
        <NativeSelect
          className="w-full"
          id={ids.table}
          onChange={(event) =>
            setDraft({
              ...draft,
              tableId: event.target.value,
              viewId: "",
              metricColumn: "",
              dateColumn: "",
            })
          }
          value={draft.tableId}
        >
          {Object.entries(tables).map(([id, table]) => (
            <NativeSelectOption key={id} value={id}>
              {table.name}
            </NativeSelectOption>
          ))}
        </NativeSelect>
      </Field>
      <Field htmlFor={ids.view} label={label("view")}>
        <NativeSelect
          className="w-full"
          id={ids.view}
          onChange={(event) =>
            setDraft({ ...draft, viewId: event.target.value })
          }
          value={draft.viewId}
        >
          <NativeSelectOption value="">
            {label("defaultView")}
          </NativeSelectOption>
          {(views[draft.tableId] ?? []).map((view) => (
            <NativeSelectOption key={view.id} value={view.id}>
              {view.name}
            </NativeSelectOption>
          ))}
        </NativeSelect>
      </Field>
    </>
  );
}

/** Records that do not fit: show what fits ("+N more"), or scroll. */
function OverflowField({
  draft,
  ids,
  label,
  setDraft,
}: {
  draft: DashboardWidgetDraft;
  ids: Record<string, string>;
  label: DashboardLabel;
  setDraft: (draft: DashboardWidgetDraft) => void;
}) {
  return (
    <Field htmlFor={ids.overflow} label={label("overflow")}>
      <NativeSelect
        className="w-full"
        id={ids.overflow}
        onChange={(event) =>
          setDraft({
            ...draft,
            overflow: event.target.value as DashboardOverflow,
          })
        }
        value={draft.overflow}
      >
        <NativeSelectOption value="fit">
          {label("overflowFit")}
        </NativeSelectOption>
        <NativeSelectOption value="scroll">
          {label("overflowScroll")}
        </NativeSelectOption>
      </NativeSelect>
    </Field>
  );
}

/** The period and trend options of a number, over one of its date columns. */
function KpiPeriodFields({
  draft,
  ids,
  label,
  locale,
  setDraft,
  tables,
  translate,
}: {
  draft: DashboardWidgetDraft;
  ids: Record<string, string>;
  label: DashboardLabel;
  locale: string;
  setDraft: (draft: DashboardWidgetDraft) => void;
  tables: Record<string, DashboardTableInfo>;
  translate: DashboardTranslate;
}) {
  const dateColumns = dashboardDateColumns(
    tables[draft.tableId]?.columns ?? []
  );
  if (!dateColumns.length) {
    return null;
  }
  return (
    <>
      <Field htmlFor={ids.date} label={label("dateColumn")}>
        <NativeSelect
          className="w-full"
          id={ids.date}
          onChange={(event) =>
            setDraft({ ...draft, dateColumn: event.target.value })
          }
          value={draft.dateColumn}
        >
          <NativeSelectOption value="">
            {label("noDateColumn")}
          </NativeSelectOption>
          {dateColumns.map((column) => (
            <NativeSelectOption key={column.id} value={column.id}>
              {column.header ?? column.id}
            </NativeSelectOption>
          ))}
        </NativeSelect>
      </Field>
      <CheckField
        checked={draft.compare}
        disabled={!draft.dateColumn}
        id={ids.compare}
        label={label("compare")}
        onChange={(compare) => setDraft({ ...draft, compare })}
      />
      {draft.compare && draft.dateColumn ? (
        <div className="grid grid-cols-2 gap-4">
          <Field htmlFor={ids.days} label={label("compareDays")}>
            <NativeSelect
              className="w-full"
              id={ids.days}
              onChange={(event) =>
                setDraft({ ...draft, compareDays: Number(event.target.value) })
              }
              value={String(draft.compareDays)}
            >
              {dashboardCompareDayOptions(locale, translate).map((option) => (
                <NativeSelectOption
                  key={option.value}
                  value={String(option.value)}
                >
                  {option.label}
                </NativeSelectOption>
              ))}
            </NativeSelect>
          </Field>
          <Field htmlFor={ids.better} label={label("compareBetter")}>
            <NativeSelect
              className="w-full"
              id={ids.better}
              onChange={(event) =>
                setDraft({
                  ...draft,
                  compareBetter: event.target.value === "down" ? "down" : "up",
                })
              }
              value={draft.compareBetter}
            >
              <NativeSelectOption value="up">
                {label("compareUp")}
              </NativeSelectOption>
              <NativeSelectOption value="down">
                {label("compareDown")}
              </NativeSelectOption>
            </NativeSelect>
          </Field>
        </div>
      ) : null}
      <CheckField
        checked={draft.sparkline}
        disabled={!draft.dateColumn}
        id={ids.sparkline}
        label={label("sparkline")}
        onChange={(sparkline) => setDraft({ ...draft, sparkline })}
      />
    </>
  );
}

function KpiFields({
  draft,
  ids,
  label,
  locale,
  setDraft,
  tables,
  translate,
}: {
  draft: DashboardWidgetDraft;
  ids: Record<string, string>;
  label: DashboardLabel;
  locale: string;
  setDraft: (draft: DashboardWidgetDraft) => void;
  tables: Record<string, DashboardTableInfo>;
  translate: DashboardTranslate;
}) {
  const numberColumns = (tables[draft.tableId]?.columns ?? []).filter(
    (column) => NUMBER_TYPES.has(String(column.type))
  );
  return (
    <>
      <Field htmlFor={ids.metric} label={label("metric")}>
        <NativeSelect
          className="w-full"
          id={ids.metric}
          onChange={(event) =>
            setDraft({
              ...draft,
              metric: event.target.value as DashboardKpiMetric,
              metricColumn:
                draft.metricColumn || (numberColumns.at(0)?.id ?? ""),
            })
          }
          value={draft.metric}
        >
          {dashboardMetricOptions(locale, translate).map((option) => (
            <NativeSelectOption key={option.value} value={option.value}>
              {option.label}
            </NativeSelectOption>
          ))}
        </NativeSelect>
      </Field>
      {draft.metric !== "count" && (
        <Field htmlFor={ids.column} label={label("metricColumn")}>
          <NativeSelect
            className="w-full"
            id={ids.column}
            onChange={(event) =>
              setDraft({ ...draft, metricColumn: event.target.value })
            }
            value={draft.metricColumn}
          >
            {numberColumns.map((column) => (
              <NativeSelectOption key={column.id} value={column.id}>
                {column.header ?? column.id}
              </NativeSelectOption>
            ))}
          </NativeSelect>
        </Field>
      )}
      <KpiPeriodFields
        draft={draft}
        ids={ids}
        label={label}
        locale={locale}
        setDraft={setDraft}
        tables={tables}
        translate={translate}
      />
    </>
  );
}

/** Picker: a table's saved view, a number or a note. */
export function AddWidgetDialog({
  label,
  locale,
  onAdd,
  onOpenChange,
  open,
  tables,
  translate,
  views,
}: AddWidgetDialogProps) {
  const prefix = useId();
  const ids = {
    type: `${prefix}-type`,
    table: `${prefix}-table`,
    view: `${prefix}-view`,
    overflow: `${prefix}-overflow`,
    metric: `${prefix}-metric`,
    column: `${prefix}-column`,
    date: `${prefix}-date`,
    compare: `${prefix}-compare`,
    days: `${prefix}-days`,
    better: `${prefix}-better`,
    sparkline: `${prefix}-sparkline`,
    title: `${prefix}-title`,
    text: `${prefix}-text`,
  };
  const initial = () => emptyWidgetDraft(Object.keys(tables).at(0) ?? "");
  const [draft, setDraft] = useState(initial);
  const submit = (event: FormEvent) => {
    event.preventDefault();
    onAdd(dashboardWidgetFromDraft(draft));
    setDraft(initial());
    onOpenChange(false);
  };
  return (
    <Dialog onOpenChange={onOpenChange} open={open}>
      <DialogContent
        className="max-h-[calc(100dvh-2rem)] overflow-y-auto"
        data-dashboard-dialog="add-widget"
      >
        <DialogHeader>
          <DialogTitle>{label("addWidgetTitle")}</DialogTitle>
        </DialogHeader>
        <form className="grid gap-4" onSubmit={submit}>
          <Field htmlFor={ids.type} label={label("widgetType")}>
            <NativeSelect
              className="w-full"
              id={ids.type}
              onChange={(event) =>
                setDraft({
                  ...draft,
                  type: event.target.value as DashboardWidgetType,
                })
              }
              value={draft.type}
            >
              <NativeSelectOption value="view">
                {label("typeView")}
              </NativeSelectOption>
              <NativeSelectOption value="kpi">
                {label("typeKpi")}
              </NativeSelectOption>
              <NativeSelectOption value="note">
                {label("typeNote")}
              </NativeSelectOption>
            </NativeSelect>
          </Field>
          {draft.type !== "note" && (
            <TableFields
              draft={draft}
              ids={ids}
              label={label}
              setDraft={setDraft}
              tables={tables}
              views={views}
            />
          )}
          {draft.type === "view" && (
            <OverflowField
              draft={draft}
              ids={ids}
              label={label}
              setDraft={setDraft}
            />
          )}
          {draft.type === "kpi" && (
            <KpiFields
              draft={draft}
              ids={ids}
              label={label}
              locale={locale}
              setDraft={setDraft}
              tables={tables}
              translate={translate}
            />
          )}
          <Field htmlFor={ids.title} label={label("widgetTitle")}>
            <Input
              id={ids.title}
              onChange={(event) =>
                setDraft({ ...draft, title: event.target.value })
              }
              value={draft.title}
            />
          </Field>
          {draft.type === "note" && (
            <Field htmlFor={ids.text} label={label("noteText")}>
              <Textarea
                id={ids.text}
                onChange={(event) =>
                  setDraft({ ...draft, text: event.target.value })
                }
                rows={4}
                value={draft.text}
              />
            </Field>
          )}
          <DialogFooter>
            <Button
              onClick={() => onOpenChange(false)}
              type="button"
              variant="outline"
            >
              {label("cancel")}
            </Button>
            <Button
              disabled={draft.type !== "note" && !draft.tableId}
              type="submit"
            >
              {label("add")}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

export interface AddFilterDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Tables of the dashboard's widgets, which a filter can apply to. */
  tables: Record<string, DashboardTableInfo>;
  label: DashboardLabel;
  onAdd: (filter: Omit<DashboardFilter, "id">) => void;
}

/** A new dashboard filter: its type, name and the column of each table it applies to. */
export function AddFilterDialog({
  label,
  onAdd,
  onOpenChange,
  open,
  tables,
}: AddFilterDialogProps) {
  const prefix = useId();
  const [type, setType] = useState<DashboardFilterType>("dateRange");
  const [name, setName] = useState("");
  const [columns, setColumns] = useState<Record<string, string>>({});
  const choices = Object.entries(tables).map(([tableId, table]) => ({
    tableId,
    table,
    columns: filterableColumns(type, table.columns),
  }));
  const targets = choices
    .map(({ tableId, columns: options }) => ({
      tableId,
      columnId: columns[tableId] ?? options.at(0)?.id ?? "",
    }))
    .filter((target) => target.columnId);
  const submit = (event: FormEvent) => {
    event.preventDefault();
    onAdd({
      type,
      label:
        name.trim() ||
        label(type === "dateRange" ? "filterDateRange" : "filterSelect"),
      targets,
    });
    setName("");
    setColumns({});
    onOpenChange(false);
  };
  return (
    <Dialog onOpenChange={onOpenChange} open={open}>
      <DialogContent
        className="max-h-[calc(100dvh-2rem)] overflow-y-auto"
        data-dashboard-dialog="add-filter"
      >
        <DialogHeader>
          <DialogTitle>{label("addFilterTitle")}</DialogTitle>
        </DialogHeader>
        <form className="grid gap-4" onSubmit={submit}>
          <Field htmlFor={`${prefix}-type`} label={label("filterType")}>
            <NativeSelect
              className="w-full"
              id={`${prefix}-type`}
              onChange={(event) => {
                setType(event.target.value as DashboardFilterType);
                setColumns({});
              }}
              value={type}
            >
              <NativeSelectOption value="dateRange">
                {label("filterDateRange")}
              </NativeSelectOption>
              <NativeSelectOption value="select">
                {label("filterSelect")}
              </NativeSelectOption>
            </NativeSelect>
          </Field>
          <Field htmlFor={`${prefix}-name`} label={label("filterName")}>
            <Input
              id={`${prefix}-name`}
              onChange={(event) => setName(event.target.value)}
              value={name}
            />
          </Field>
          {choices.map(({ tableId, table, columns: options }) => (
            <Field
              htmlFor={`${prefix}-${tableId}`}
              key={tableId}
              label={label("filterColumn", { table: table.name })}
            >
              <NativeSelect
                className="w-full"
                id={`${prefix}-${tableId}`}
                onChange={(event) =>
                  setColumns({ ...columns, [tableId]: event.target.value })
                }
                value={columns[tableId] ?? options.at(0)?.id ?? ""}
              >
                <NativeSelectOption value="">
                  {label("notApplied")}
                </NativeSelectOption>
                {options.map((column) => (
                  <NativeSelectOption key={column.id} value={column.id}>
                    {column.header ?? column.id}
                  </NativeSelectOption>
                ))}
              </NativeSelect>
            </Field>
          ))}
          {targets.length === 0 && (
            <p className="text-muted-foreground text-sm">
              {label("noFilterColumns")}
            </p>
          )}
          <DialogFooter>
            <Button
              onClick={() => onOpenChange(false)}
              type="button"
              variant="outline"
            >
              {label("cancel")}
            </Button>
            <Button disabled={targets.length === 0} type="submit">
              {label("add")}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { CalendarIcon, ChevronDown, X } from "lucide-react";
import { useId, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import {
  Popover,
  PopoverContent,
  PopoverTitle,
  PopoverTrigger,
} from "@/components/ui/popover";
import { formWeekStart } from "@/components/ui/yayaw-table/utils/form-view";
import { tagAppearance } from "@/components/ui/yayaw-table/utils/tag-colors";
import { cn } from "@/lib/utils";
import "@/components/ui/yayaw-table/utils/tag-colors.css";
import {
  type DashboardDateRange,
  type DashboardFilter,
  type DashboardFilterOption,
  type DashboardTableInfo,
  type DashboardTranslate,
  dashboardDateRangeText,
  dashboardDay,
  dashboardDayValue,
  dashboardFilterColoredTags,
  dashboardFilterColumn,
  dashboardFilterOptions,
  dashboardFilterTargetsLabel,
  isDashboardFilterActive,
} from "./dashboard-model";
import type { DashboardLabel } from "./dashboard-widget";

type WeekStart = 0 | 1 | 2 | 3 | 4 | 5 | 6;

interface FilterControlProps {
  filter: DashboardFilter;
  tables: Record<string, DashboardTableInfo>;
  editing: boolean;
  label: DashboardLabel;
  locale: string;
  translate: DashboardTranslate;
  onChange: (value: DashboardDateRange | string[] | undefined) => void;
  onRemove: () => void;
  /** Id of the "Applies to …" text describing the control. */
  describedBy?: string;
}

/** Outside edit mode the filter's name leads its button, as a compact chip. */
function TriggerName({ filter, editing }: FilterControlProps) {
  return editing ? null : (
    <span className="shrink-0 text-muted-foreground" data-filter-name="">
      {filter.label}
    </span>
  );
}

/** Month captions, weekdays and day names in the dashboard's language. */
function useCalendarText(locale: string) {
  return useMemo(() => {
    const month = new Intl.DateTimeFormat(locale, {
      month: "long",
      year: "numeric",
    });
    const weekday = new Intl.DateTimeFormat(locale, { weekday: "short" });
    const day = new Intl.DateTimeFormat(locale, { dateStyle: "full" });
    return {
      formatters: {
        formatCaption: (date: Date) => month.format(date),
        formatWeekdayName: (date: Date) => weekday.format(date),
      },
      labels: { labelDayButton: (date: Date) => day.format(date) },
    };
  }, [locale]);
}

/** The Form view's popover calendar, picking a range of days. */
function DateRangeControl(props: FilterControlProps) {
  const { describedBy, filter, label, locale, onChange, tables, translate } =
    props;
  const text = useCalendarText(locale);
  const range = (filter.value ?? {}) as DashboardDateRange;
  const from = dashboardDay(range.start);
  const to = dashboardDay(range.end);
  const shown = dashboardDateRangeText(
    filter.value,
    locale,
    translate,
    dashboardFilterColumn(filter, tables)
  );
  return (
    <Popover>
      <PopoverTrigger
        render={
          <Button
            aria-describedby={describedBy}
            aria-label={`${filter.label}: ${shown}`}
            className="h-8 min-w-56 max-w-full justify-start gap-2 px-2.5 font-normal"
            data-filter-trigger=""
            size="sm"
            type="button"
            variant="outline"
          />
        }
      >
        <CalendarIcon aria-hidden="true" className="text-muted-foreground" />
        <TriggerName {...props} />
        <span
          className={cn(
            "min-w-0 flex-1 truncate text-left",
            !(from || to) && "text-muted-foreground"
          )}
          data-filter-value=""
        >
          {shown}
        </span>
        <ChevronDown aria-hidden="true" className="text-muted-foreground" />
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-auto gap-0 p-0"
        data-dashboard-filter-popup={filter.id}
      >
        <Calendar
          className="[--cell-size:--spacing(8)]"
          defaultMonth={from ?? to}
          formatters={text.formatters}
          labels={text.labels}
          lang={locale}
          mode="range"
          onSelect={(next) =>
            onChange({
              start: next?.from ? dashboardDayValue(next.from) : undefined,
              end: next?.to ? dashboardDayValue(next.to) : undefined,
            })
          }
          selected={from || to ? { from, to } : undefined}
          weekStartsOn={formWeekStart(locale) as WeekStart}
        />
        {from || to ? (
          <div className="flex justify-end border-t p-2">
            <Button
              onClick={() => onChange(undefined)}
              size="sm"
              type="button"
              variant="ghost"
            >
              {label("clear")}
            </Button>
          </div>
        ) : null}
      </PopoverContent>
    </Popover>
  );
}

/** An option as the table shows it: a tag. */
function OptionTag({
  colored,
  option,
}: {
  colored: boolean;
  option: DashboardFilterOption;
}) {
  const appearance = tagAppearance(option.value, colored);
  return (
    <span
      className={cn(
        "yayaw-tag inline-flex max-w-full items-center truncate rounded-md px-2 py-0.5 text-xs",
        appearance.className
      )}
      data-colored={appearance.colored}
      data-custom-color={appearance.className ? "" : undefined}
      style={appearance.style}
    >
      {option.label}
    </span>
  );
}

/** The library's option dropdown: "All" or the chosen options, shown as tags. */
function SelectControl(props: FilterControlProps) {
  const { describedBy, filter, label, onChange, tables } = props;
  const values = Array.isArray(filter.value) ? filter.value : [];
  const options = dashboardFilterOptions(filter, tables);
  const colored = dashboardFilterColoredTags(filter, tables);
  const chosen = options.filter((option) => values.includes(option.value));
  const toggle = (value: string) => {
    const next = values.includes(value)
      ? values.filter((item) => item !== value)
      : [...values, value];
    onChange(next.length ? next : undefined);
  };
  return (
    <Popover>
      <PopoverTrigger
        render={
          <Button
            aria-describedby={describedBy}
            aria-label={filter.label}
            className="h-8 min-w-44 max-w-80 justify-start gap-1.5 px-2 font-normal"
            data-filter-trigger=""
            size="sm"
            type="button"
            variant="outline"
          />
        }
      >
        <TriggerName {...props} />
        <span
          className="flex min-w-0 flex-1 items-center gap-1 overflow-hidden"
          data-filter-value=""
        >
          {chosen.length ? (
            chosen.map((option) => (
              <OptionTag colored={colored} key={option.value} option={option} />
            ))
          ) : (
            <span className="px-0.5">{label("any")}</span>
          )}
        </span>
        <ChevronDown aria-hidden="true" className="text-muted-foreground" />
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-64 gap-1 p-1"
        data-dashboard-filter-popup={filter.id}
      >
        <PopoverTitle className="sr-only">{filter.label}</PopoverTitle>
        <fieldset
          aria-label={filter.label}
          className="m-0 grid max-h-64 min-w-0 gap-0.5 overflow-auto border-0 p-0"
        >
          <label className="flex cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent">
            <input
              checked={values.length === 0}
              onChange={() => onChange(undefined)}
              type="checkbox"
            />
            <span>{label("any")}</span>
          </label>
          {options.map((option) => (
            <label
              className="flex cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent"
              key={option.value}
            >
              <input
                aria-label={option.label}
                checked={values.includes(option.value)}
                onChange={() => toggle(option.value)}
                type="checkbox"
              />
              <OptionTag colored={colored} option={option} />
            </label>
          ))}
        </fieldset>
      </PopoverContent>
    </Popover>
  );
}

/**
